class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        q, res = deque(), []            # q 存下标，对应的值递减
        for i, x in enumerate(nums):
            while q and nums[q[-1]] <= x:
                q.pop()                 # 队尾比新数小，没用了
            q.append(i)
            if q[0] <= i - k:
                q.popleft()             # 队头滑出窗口
            if i >= k - 1:
                res.append(nums[q[0]])
        return res

